import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- NEW TESTS FOR ISSUE #1 ---

test('brick bounce: top hit should flip vy and push out', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.bricks = [brick];
  // Ball moving UP, hits the BOTTOM face of the brick
  // Ball is at (125, 118), radius 7. Ball bottom is at 125, top is at 111.
  // Brick bottom is at 120. Overlap: ball top (111) < brick bottom (120).
  state.ball = { x: 125, y: 118, r: 7, vx: 0, vy: -100 };

  const ctx = { 
    fillRect: () => {}, 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {} 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should be destroyed');
  assert.ok(state.ball.vy > 0, 'vy should be flipped to DOWN');
  assert.ok(state.ball.y >= 120 + 7, 'Ball should be pushed out of the brick bottom');
});

test('brick bounce: side hit should flip vx and push out', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.bricks = [brick];
  // Ball moving RIGHT, hits the LEFT face of the brick
  // Ball x=95, r=7 => right edge 102. Brick x=100. Overlap.
  state.ball = { x: 95, y: 110, r: 7, vx: 100, vy: 0 };

  const ctx = { 
    fillRect: () => {}, 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {} 
  };

  frame(ctx, state);

  assert.equal(brick.alive, false, 'Brick should be destroyed');
  assert.ok(state.ball.vx < 0, 'vx should be flipped to LEFT');
  assert.ok(state.ball.x <= 100 - 7, 'Ball should be pushed out of the brick left');
});

test('brick bounce: corner hit should flip both', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.bricks = [brick];
  // Ball hits the bottom-left corner.
  // Position the ball such that it penetrates both x and y faces equally.
  state.ball = { x: 95, y: 118, r: 7, vx: 100, vy: -100 };

  const ctx = { 
    fillRect: () => {}, 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {} 
  };

  frame(ctx, state);

  assert.ok(state.ball.vx < 0, 'vx should be flipped');
  assert.ok(state.ball.vy > 0, 'vy should be flipped');
});

test('tunnelling: fast ball should still hit brick (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.bricks = [brick];

  // Level 6 speed: 710 px/s. 
  // Let's simulate a step where the ball jumps over the brick.
  // Ball starts at y=130 (below brick), vx=0, vy=-1000 (very fast UP).
  // In one step of 0.05s, ball moves 50px UP to y=80.
  // Brick is at y=100, h=20 (bottom=120). 
  // The ball was at 130, then 80. It jumped over the brick's 100-120 range.
  state.ball = { x: 125, y: 130, r: 7, vx: 0, vy: -1000 };

  // We need a way to test tunnelling. Since currently tunnelling 
  // detection is not implemented, this test should fail (the brick stays alive).
  // We'll call step() and then frame().
  step(state, 0.05); // ball.y becomes 80

  const ctx = { 
    fillRect: () => {}, 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {} 
  };
  frame(ctx, state);

  assert.equal(brick.alive, false, 'Ball should have hit the brick via sweep/tunnelling check');
});

function belowField() {
  return 500;
}

