export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// New function to handle collision and bounce logic.
// It returns true if a collision occurred.
function resolveBrickCollision(state, brick, prevBall) {
  const { ball } = state;

  // Tunnelling check (Sweep): 
  // Check if the ball passed through the brick between prevBall and ball.
  // We check if the path intersects the brick's AABB.
  let hit = collides(ball, brick);
  if (!hit && prevBall) {
    // Simple sweep: check if the line segment (prevBall, ball) intersects the brick
    // This is a bit more complex. A simpler version: check mid-points or check if
    // the ball was on one side and is now on the other.

    // Check if ball's center passed through the brick's expanded bounds.
    const minX = Math.min(prevBall.x, ball.x) - ball.r;
    const maxX = Math.max(prevBall.x, ball.x) + ball.r;
    const minY = Math.min(prevBall.y, ball.y) - ball.r;
    const maxY = Math.max(prevBall.y, ball.y) + ball.r;

    if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
      hit = true;
    }
  }

  if (!hit) return false;

  // Collision resolution (Per-face bounce)
  // Calculate penetrations on each axis.
  const overlapLeft = (ball.x + ball.r) - brick.x;
  const overlapRight = (brick.x + brick.w) - (ball.x - ball.r);
  const overlapTop = (ball.y + ball.r) - brick.y;
  const overlapBottom = (brick.y + brick.h) - (ball.y - ball.r);

  const minOverlapX = Math.min(overlapLeft, overlapRight);
  const minOverlapY = Math.min(overlapTop, overlapBottom);

  if (minOverlapX < minOverlapY) {
    // Side hit
    ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx); // Ensure it moves away
    // Use current vx sign if it's already moving away to avoid sticking, 
    // but for a standard bounce, we flip it.
    // Better: if moving RIGHT and hitting LEFT side, flip to LEFT.
    if (ball.vx > 0 && overlapLeft < overlapRight) ball.vx = -Math.abs(ball.vx);
    else if (ball.vx < 0 && overlapRight < overlapLeft) ball.vx = Math.abs(ball.vx);
    else ball.vx = -ball.vx; // fallback

    // Push out
    if (overlapLeft < overlapRight) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
  } else if (minOverlapY < minOverlapX) {
    // Top/Bottom hit
    if (ball.vy > 0 && overlapTop < overlapBottom) ball.vy = -Math.abs(ball.vy);
    else if (ball.vy < 0 && overlapBottom < overlapTop) ball.vy = Math.abs(ball.vy);
    else ball.vy = -ball.vy; // fallback

    // Push out
    if (overlapTop < overlapBottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  } else {
    // Corner hit (equal overlaps)
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;

    // Push out to nearest corner (approximate)
    if (overlapLeft < overlapRight) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
    if (overlapTop < overlapBottom) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
  }

  return true;
}

